import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"Clash 与 Stash 兼容吗？","description":"说明如何把 Stash 的 Clash YAML、订阅、节点、覆写、脚本和规则需求迁移到 Clash iOS。","frontmatter":{"title":"Clash 与 Stash 兼容吗？","description":"说明如何把 Stash 的 Clash YAML、订阅、节点、覆写、脚本和规则需求迁移到 Clash iOS。","head":[["meta",{"name":"keywords","content":"Stash转Clash,Stash订阅,Stash配置,Stash YAML,Clash iOS,mihomo iOS"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"FAQPage\\",\\"mainEntity\\":[{\\"@type\\":\\"Question\\",\\"name\\":\\"Stash 配置可以用于 Clash 吗？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"标准 Clash 或 mihomo YAML 可以直接导入；Stash 的覆写、HTTP 引擎、MITM、重写、脚本和设备设置可使用 Clash 对应功能重新建立。\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Stash 的订阅可以用于 Clash 吗？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"可以，只要订阅返回标准 Clash 或 mihomo YAML。可以把同一个 URL 添加到 Clash，必要时切换订阅 User-Agent。\\"}}]}"]]},"headers":[],"relativePath":"zh/guide/compatibility/stash.md","filePath":"zh/guide/compatibility/stash.md","lastUpdated":0}`),a={name:`zh/guide/compatibility/stash.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="clash-与-stash-兼容吗" tabindex="-1">Clash 与 Stash 兼容吗？ <a class="header-anchor" href="#clash-与-stash-兼容吗" aria-label="Permalink to “Clash 与 Stash 兼容吗？”">​</a></h1><p><strong>标准 Clash / mihomo YAML 与订阅可以直接使用。</strong></p><p>Stash 官方文档说明它可以导入 <a href="https://stash.wiki/en/get-started" target="_blank" rel="noreferrer">Stash / Clash 格式配置</a>，并且<a href="https://stash.wiki/configuration/example-config" target="_blank" rel="noreferrer">所有配置文件使用 YAML</a>。因此，只要你在 Stash 中使用的是标准 Clash 或 mihomo YAML，就可以直接导入 Clash。</p><h2 id="什么可以直接迁移" tabindex="-1">什么可以直接迁移？ <a class="header-anchor" href="#什么可以直接迁移" aria-label="Permalink to “什么可以直接迁移？”">​</a></h2><ul><li>标准 Clash / mihomo YAML 配置；</li><li>返回 Clash / mihomo YAML 的远程订阅；</li><li>节点、Proxy Provider 与 Rule Provider；</li><li>策略组、健康检查和路由规则；</li><li>双方均支持的 DNS 与其他配置字段。</li></ul><h2 id="最省事的迁移方式" tabindex="-1">最省事的迁移方式 <a class="header-anchor" href="#最省事的迁移方式" aria-label="Permalink to “最省事的迁移方式”">​</a></h2><ol><li>复制 Stash 当前配置使用的订阅 URL。</li><li>在 Clash 中添加该远程配置。</li><li>如果 Stash 使用本地 YAML，也可以通过文件或系统“共享”导入 Clash。</li><li>更新配置并检查节点、策略组与规则。</li><li>服务商提供多种格式时，切换订阅 User-Agent，选择 Clash / mihomo 输出。</li></ol><h2 id="在-clash-中重新建立的-stash-功能" tabindex="-1">在 Clash 中重新建立的 Stash 功能 <a class="header-anchor" href="#在-clash-中重新建立的-stash-功能" aria-label="Permalink to “在 Clash 中重新建立的 Stash 功能”">​</a></h2><ul><li>将覆写文件整合为清晰的 mihomo YAML；</li><li>使用对应功能建立 HTTP 引擎、MITM 与证书需求；</li><li>使用 Clash 规则与对应功能建立 URL Rewrite 和脚本需求；</li><li>按自己的使用习惯设置按需连接、同步、远程控制与 App 偏好。</li></ul><p>如果 Stash 使用多个覆写文件动态生成配置，可以先导出或整理为一份最终的标准 mihomo YAML，再把 Stash 扩展需求映射到 Clash 的对应功能。</p><h2 id="可以继续使用同一台服务器吗" tabindex="-1">可以继续使用同一台服务器吗？ <a class="header-anchor" href="#可以继续使用同一台服务器吗" aria-label="Permalink to “可以继续使用同一台服务器吗？”">​</a></h2><p>两款 App 使用相同的标准节点配置时，同一台服务器可以直接使用。</p><p>返回<a href="/clash.md/zh/guide/compatibility">兼容性总览</a>。</p>`,13)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};